import{_ as e,o as a,c as l,a2 as o}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"董事会与公司治理","description":"巴菲特对董事会职能、代理问题和股东维权的深度思考","frontmatter":{"title":"董事会与公司治理","description":"巴菲特对董事会职能、代理问题和股东维权的深度思考"},"headers":[],"relativePath":"02_concepts/corporate-governance.md","filePath":"02_concepts/corporate-governance.md"}'),r={name:"02_concepts/corporate-governance.md"};function h(n,t,p,i,s,d){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="董事会与公司治理" tabindex="-1">董事会与公司治理 <a class="header-anchor" href="#董事会与公司治理" aria-label="Permalink to &quot;董事会与公司治理&quot;">​</a></h1><blockquote><p>&quot;薪酬顾问公司知道他们的客户是谁——是聘请他们的CEO，而不是股东。这种利益冲突是系统性缺陷。&quot; —— <a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2003年</p></blockquote><p>公司治理是<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1980年代至2000年代反复讨论的核心议题。他对代理问题（Agent Problem）的批判、对董事会失灵的揭露，以及对股东维权的实践，构成了理解现代公司制度的重要视角。</p><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1985年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">股权激励天然不公平——拿股东价值</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1988年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">为什么不合格CEO位置最稳</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1992年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">所罗门危机：巴菲特担任临时董事长</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2001年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">通用再保险的治理失败</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2003年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">薪酬顾问的利益冲突</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2008年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">金融危机的根源：薪酬与风险脱钩</td></tr></tbody></table><hr><h2 id="一、代理问题-现代公司制度的根本矛盾" tabindex="-1">一、代理问题：现代公司制度的根本矛盾 <a class="header-anchor" href="#一、代理问题-现代公司制度的根本矛盾" aria-label="Permalink to &quot;一、代理问题：现代公司制度的根本矛盾&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1985年首次系统阐述代理问题：</p><blockquote><p>&quot;在典型的期权计划中，CEO可以在股价下跌时稳坐钓鱼台——他们的奖金与股价表现无关。如果他们把公司搞砸了，期权仍然有效，可以等到市场好转时行权。这种激励是向下的，不是向上的。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1985年致股东信</p></blockquote><p><strong>代理问题的核心</strong>：管理者（代理人）的利益与股东（委托人）的利益往往不一致。在缺乏有效约束的情况下，管理者会优先追求自身利益而非股东利益。</p><hr><h2 id="二、为什么不合格的ceo最难被替换" tabindex="-1">二、为什么不合格的CEO最难被替换 <a class="header-anchor" href="#二、为什么不合格的ceo最难被替换" aria-label="Permalink to &quot;二、为什么不合格的CEO最难被替换&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1988年对这一问题做了最尖锐的批判：</p><blockquote><p>&quot;秘书打字不够快马上走人，销售卖不出货马上走人，但是CEO不行。业绩不好位置还特别稳，为什么？&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1988年致股东信</p></blockquote><p><strong>原因分析：</strong></p><ol><li>CEO的业绩衡量标准模糊，不合格也很难说清楚</li><li>董事会成员往往由CEO挑选，批评老板等于自断前程</li><li>CEO有大量资源可以影响舆论和董事会判断</li><li>&quot;老板就是老板，谁也不说&quot;</li></ol><hr><h2 id="三、所罗门危机-治理失败的经典案例" tabindex="-1">三、所罗门危机：治理失败的经典案例 <a class="header-anchor" href="#三、所罗门危机-治理失败的经典案例" aria-label="Permalink to &quot;三、所罗门危机：治理失败的经典案例&quot;">​</a></h2><p>1991-1992年，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>被迫担任所罗门公司临时董事长，这是他唯一一次&quot;出山&quot;担任上市公司高管。</p><blockquote><p>&quot;我不是来当CEO的，我是来保护公司声誉的。信任是商业的基础，破坏它需要几十年，修复它需要几百年。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1991年</p></blockquote><p>所罗门危机的教训：</p><ul><li><strong>风险管理体系失效</strong>：交易员违规操作，长期无人发现</li><li><strong>董事会监督失职</strong>：内部审计委员会形同虚设</li><li><strong>激励机制扭曲</strong>：短期利润驱动了冒险行为</li></ul><blockquote><p>&quot;所罗门的问题不是一个人造成的，是一套制度失败的结果。当激励完全朝一个方向倾斜时，再多的人也无法阻止灾难。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1992年致股东信</p></blockquote><hr><h2 id="四、通用再保险-又一次治理失败" tabindex="-1">四、通用再保险：又一次治理失败 <a class="header-anchor" href="#四、通用再保险-又一次治理失败" aria-label="Permalink to &quot;四、通用再保险：又一次治理失败&quot;">​</a></h2><p>2001年，<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>旗下通用再保险（General Re）被曝出准备金严重不足，亏损8亿美元。</p><blockquote><p>&quot;通用再保险在承保时未设置应有的保护措施。这是管理层的判断错误，不是行业问题。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2001年致股东信</p></blockquote><p><strong>教训</strong>：再好的公司，一旦治理松懈，就会出问题。<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>迅速介入，更换了管理层，建立了新的风险控制体系。</p><hr><h2 id="五、金融危机-薪酬与风险的根本性脱钩" tabindex="-1">五、金融危机：薪酬与风险的根本性脱钩 <a class="header-anchor" href="#五、金融危机-薪酬与风险的根本性脱钩" aria-label="Permalink to &quot;五、金融危机：薪酬与风险的根本性脱钩&quot;">​</a></h2><p>2008年金融危机后，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对华尔街公司治理做了最深刻的批判：</p><blockquote><p>&quot;这次危机的根本原因之一，是太多华尔街高管的薪酬与短期收益挂钩，而与长期风险无关。他们被激励去冒险——赢了是自己的，亏了是股东和纳税人的。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2008年致股东信</p></blockquote><p><strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>提出的解决框架：</strong></p><ol><li>薪酬应与<strong>长期</strong>业绩挂钩，而非短期股价</li><li>董事会必须真正独立，真正代表股东利益</li><li>风险承担者应与股东&quot;同甘共苦&quot;</li></ol><hr><h2 id="六、伯克希尔的治理哲学" tabindex="-1">六、伯克希尔的治理哲学 <a class="header-anchor" href="#六、伯克希尔的治理哲学" aria-label="Permalink to &quot;六、伯克希尔的治理哲学&quot;">​</a></h2><p><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>的公司治理与华尔街截然不同：</p><blockquote><p>&quot;在<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>，我们的董事不是由管理层挑选的。我们的董事是<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>的长期股东，他们的利益与所有股东一致。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2012年致股东信</p></blockquote><p><strong><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>治理的三大支柱：</strong></p><ol><li><strong>诚信为本</strong>——<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>选择董事的首要标准是诚信，不是能力</li><li><strong>利益一致</strong>——董事自己持有<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>股票，与股东利益绑定</li><li><strong>充分授权</strong>——CEO有充分的经营自主权，不需要层层审批</li></ol><hr><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>议题</th><th><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>观点</th></tr></thead><tbody><tr><td>股权激励</td><td>固定价格期权天然不公平，应与整体业绩绑定</td></tr><tr><td>董事会职责</td><td>必须真正独立，批评管理层是职责所在</td></tr><tr><td>薪酬顾问</td><td>利益冲突的系统性缺陷，需要变革</td></tr><tr><td>风险治理</td><td>激励机制扭曲是大多数金融灾难的根本原因</td></tr><tr><td>伯克希尔的做法</td><td>诚信第一，利益一致，充分授权</td></tr></tbody></table><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./executive-compensation.html">高管薪酬 (Executive Compensation)</a> — 薪酬制度的深层问题</li><li><a href="./management.html">管理层 (Management)</a> — 优秀管理者的识别标准</li><li><a href="./reputation.html">声誉 (Reputation)</a> — 声誉是商业的命脉</li></ul>',47)])])}const f=e(r,[["render",h]]);export{u as __pageData,f as default};
